package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.protocol.packets.interface_.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.entity.entities.player.pages.InteractiveCustomUIPage;import com.hypixel.hytale.server.core.ui.builder.*;import com.hypixel.hytale.server.core.universe.PlayerRef;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import dev.astralreach.core.*;
final class StationSystemsPage extends InteractiveCustomUIPage<StationPage.Action>{
 private final RocketRegistry.Cell at;private long updated;
 StationSystemsPage(PlayerRef p,RocketRegistry.Cell at){super(p,CustomPageLifetime.CanDismiss,StationPage.Action.CODEC);this.at=at;}
 static void open(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,RocketRegistry.Cell at){StationService.docked(s,r,p);s.getComponent(r,Player.getComponentType()).getPageManager().openCustomPage(r,s,new StationSystemsPage(p,at));}
 private void labels(Store<EntityStore>s,Ref<EntityStore>r,UICommandBuilder c){var st=StationService.docked(s,r,playerRef);var status=StationSystems.status(s,st);boolean owner=st.owner.equals(playerRef.getUuid());c.set("#Rename.Disabled",!owner);c.set("#StationName.Text",st.title());c.set("#Solar.Text","SOLAR · "+(status.sunlit()?status.panels()*4:0)+" charge/s · "+(status.sunlit()?"sunlit":"eclipse"));c.set("#Draw.Text","LIFE SUPPORT · "+status.consumers()*3+" charge/s");c.set("#Stored.Text",Math.round(status.charge())+" / "+status.batteries()*2400+" charge");c.set("#Battery.Value",status.batteries()==0?0:status.charge()/(status.batteries()*2400));c.set("#Reserve.Text","Dark reserve · "+(status.consumers()>0?NativeUi.duration(status.charge()/(status.consumers()*3)):"No active consumers"));var d=at==null?null:OxygenService.data(s).diffusers.get(at);boolean controls=d!=null&&d.owner.equals(playerRef.getUuid())&&RocketService.near(s,r,at);c.set("#Toggle.Disabled",!controls);c.set("#Load.Disabled",!controls||d.items.size()>=4);c.set("#Collect.Disabled",!controls||d.items.isEmpty());c.set("#Toggle.Text",d!=null&&d.enabled?"Disable":"Enable");c.set("#Oxygen.Text",d==null?"No life-support unit selected":"OXYGEN · "+NativeUi.duration(d.oxygen()/OxygenSupply.stationRate(d.people)));c.set("#Status.Text",d==null?"Solar and batteries share the station bus":d.powered?"PRESSURISING":!d.enabled?"Disabled":d.oxygen()<=0?"Load an oxygen canister":"No power · add solar or a charged battery");c.set("#People.Text",d==null?"":d.people+(d.people==1?" person supplied":" people supplied"));for(int i=0;i<4;i++){boolean present=d!=null&&i<d.items.size();c.set("#Canister"+i+".Visible",present);if(present)c.set("#Canister"+i+".ItemId",d.items.get(i).getItemId());c.set("#Charge"+i+".Value",present?OxygenCanisters.remaining(d.items.get(i))/OxygenCanisters.capacity(d.items.get(i)):0);}}
 @Override public void build(Ref<EntityStore>r,UICommandBuilder c,UIEventBuilder e,Store<EntityStore>s){c.append("Pages/AstralReach/StationSystems.ui");labels(s,r,c);c.set("#CallSign.Value",StationService.docked(s,r,playerRef).title());for(String a:new String[]{"Load","Collect","Toggle","Back"})e.addEventBinding(CustomUIEventBindingType.Activating,"#"+a,EventData.of("Action",a),false);e.addEventBinding(CustomUIEventBindingType.Activating,"#Rename",EventData.of("Action","Rename").append("@Name","#CallSign.Value"),false);NativeUi.cue(s,playerRef);}
 void refresh(Store<EntityStore>s,Ref<EntityStore>r){if(System.nanoTime()-updated<1_000_000_000L)return;updated=System.nanoTime();try{var c=new UICommandBuilder();labels(s,r,c);sendUpdate(c,false);}catch(IllegalArgumentException ex){close();}}
 @Override public void handleDataEvent(Ref<EntityStore>r,Store<EntityStore>s,StationPage.Action a){s.getExternalData().getWorld().execute(()->{if(!r.isValid()||r.getStore()!=s||s.getComponent(r,Player.getComponentType()).getPageManager().getCustomPage()!=this)return;try{var st=StationService.docked(s,r,playerRef);if(a.action.equals("Back")){StationPage.open(s,r,playerRef);return;}if(a.action.equals("Rename")){if(!st.owner.equals(playerRef.getUuid()))throw new IllegalArgumentException("Only the station owner can rename it.");st.rename(a.name);RocketService.cue(s,playerRef,"AR_observatory_handling",StationService.cell(st.layout.core()));}else if(at!=null&&StationSystems.station(s,at)==st)OxygenService.action(s,r,playerRef,at,a.action);updated=0;refresh(s,r);}catch(IllegalArgumentException ex){AstralReachPlugin.message(playerRef,ex.getMessage());}});}
}
